class Lesson {
  final String title,desc,code,question,explanation;
  final List<String> options;
  final int answer;
  const Lesson(this.title,this.desc,this.code,this.question,this.options,this.answer,this.explanation);
}
class Course {
  final String title,desc;
  final Color color;
  final IconData icon;
  final List<Lesson> lessons;
  const Course(this.title,this.desc,this.color,this.icon,this.lessons);
}
