class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int page=0,xp=0;Set<String> done={},saved={};String search='';
@override void initState(){super.initState();_load();}
Future<void> _load()async{final p=await SharedPreferences.getInstance();if(!mounted)return;setState((){done=p.getStringList('codage_done')?.toSet()??{};saved=p.getStringList('codage_saved')?.toSet()??{};xp=p.getInt('codage_xp')??done.length*25;});}
String key(Course c,Lesson l)=>c.title+'::'+l.title;
Future<void> _finish(String k)async{if(done.contains(k))return;final p=await SharedPreferences.getInstance();setState((){done.add(k);xp+=25;});await p.setStringList('codage_done',done.toList());await p.setInt('codage_xp',xp);}
Future<void> _bookmark(String k)async{final p=await SharedPreferences.getInstance();setState(()=>saved.contains(k)?saved.remove(k):saved.add(k));await p.setStringList('codage_saved',saved.toList());}
int get total=>courses.fold<int>(0,(s,c)=>s+c.lessons.length);
double get ratio=>total==0?0:done.length/total;
